const std = @import("std");

const BloomFilter = struct {
    bits: u64 = 0,

    fn hash1(self: BloomFilter, s: []const u8) u6 {
        var h: u64 = 5381;
        for (s) |ch| h = h *% 33 +% ch;
        return @truncate(h);
    }
    fn hash2(self: BloomFilter, s: []const u8) u6 {
        var h: u64 = 0;
        for (s) |ch| h = h *% 65599 +% ch;
        return @truncate(h);
    }
    fn insert(self: *BloomFilter, s: []const u8) void {
        self.bits |= (@as(u64, 1) << self.hash1(s));
        self.bits |= (@as(u64, 1) << self.hash2(s));
    }
    fn mightContain(self: BloomFilter, s: []const u8) bool {
        const b1 = self.bits & (@as(u64, 1) << self.hash1(s));
        const b2 = self.bits & (@as(u64, 1) << self.hash2(s));
        return b1 != 0 and b2 != 0;
    }
};

pub fn main() !void {
    var bf = BloomFilter{};
    bf.insert("apple");
    bf.insert("banana");

    std.debug.print("apple: {}\n", .{bf.mightContain("apple")});
    std.debug.print("grape: {}\n", .{bf.mightContain("grape")});
}

